@-moz-document domain("soundcloud.com") {
html,
body {
  background-color: #030905 !important;
  color: #8BFF9F !important;
}

body {
  background-image: linear-gradient(180deg, rgba(1, 7, 3, 0.32) 0%, rgba(1, 7, 3, 0.17) 48%, rgba(1, 7, 3, 0.32) 100%),
    url("data:image/webp;base64,") !important;
  background-size: cover, cover !important;
  background-position: center center, center center !important;
  background-repeat: no-repeat, no-repeat !important;
  background-attachment: fixed, fixed !important;
  min-height: 100vh;
}

body:before {
  content: "";
  position: fixed;
  top: 43%;
  left: 0;
  right: 0;
  height: 25vh;
  pointer-events: none;
  z-index: 0;
  opacity: 0.21;
  background-image: linear-gradient(180deg,
    transparent 0%, rgba(0, 255, 102, 0.10) 52%, transparent 100%);
}

body:after {
  content: "";
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 2147483646;
  pointer-events: none;
  opacity: 0.30;
  background-image: repeating-linear-gradient(0deg,
    rgba(0, 0, 0, 0.0) 0px,
    rgba(0, 0, 0, 0.0) 2px,
    rgba(0, 0, 0, 0.32) 3px,
    rgba(0, 0, 0, 0.32) 4px);
}

